use mabi_meter_core::{capture_file::Input,combat::Stamp,damage_wire::{Fields,Survey,EVIDENCE_CAPACITY},protocol,replay::Replay,transport::{Flow,Segment}};
fn body(source:u64,target:u64,raw:u64,aux:u64)->Vec<u8>{let mut p=vec![0;53];for (i,n) in [source,target,raw,aux].into_iter().enumerate(){p[i*8..i*8+8].copy_from_slice(&n.to_le_bytes());}p}
fn at(frame:u64)->Stamp{Stamp{process:1,continuity:0,context:3,frame,order:frame,timestamp_ns:frame,tcp_byte:frame*62}}
fn segment(payload:Vec<u8>)->Input{Input::Segment(Segment{seq:100,timestamp_ns:1,payload,flow:Flow{src:"192.0.2.1".into(),sport:1234,dst:"192.0.2.2".into(),dport:2345},syn:false,fin:false,rst:false,ack:true})}
#[test]fn all_fifty_three_bytes_roundtrip_including_ignored_prefixes_and_tail(){let p:Vec<_>=(0..53).collect();let f=Fields::parse(&p).unwrap();assert_eq!(f.prefix_bytes().as_slice(),p);assert_eq!(f.raw_tail.as_slice(),&p[39..]);}
#[test]fn candidate_keeps_raw_amount_and_checked_failure_cases(){let f=Fields::parse(&body(1,2,957,915)).unwrap();assert_eq!(f.hp_impact_candidate(),Some(42));assert_eq!(f.raw_amount,957);assert_eq!(Fields::parse(&body(1,2,100,100)).unwrap().hp_impact_candidate(),Some(0));assert_eq!(Fields::parse(&body(1,2,10,11)).unwrap().hp_impact_candidate(),None);assert_eq!(Fields::parse(&body(1,2,u64::MAX,u64::MAX)).unwrap().hp_impact_candidate(),None);}
#[test]fn invalid_legacy_identity_and_sentinel_are_retained_before_gates(){let p=body(0,0,u64::MAX,123);let f=Fields::parse(&p).unwrap();assert_eq!(f.raw_amount,u64::MAX);assert!(protocol::damage(&p).is_err());let mut s=Survey::default();s.observe(at(1),2,&p,true);assert_eq!(s.counts.parsed,1);assert_eq!(s.counts.outside_legacy_gate,1);assert_eq!(s.observations().next().unwrap().fields,f);}
#[test]fn extensions_are_visible_without_extrapolating_the_candidate_model(){let mut p=body(1,2,100,20);p.extend([9;12]);let f=Fields::parse(&p).unwrap();assert_eq!(f.body_length,65);assert_eq!(f.prefix_bytes().as_slice(),&p[..53]);assert_eq!(f.hp_impact_candidate(),None);assert_eq!(protocol::damage(&p).unwrap().amount,100);}
#[test]fn candidate_does_not_inherit_the_legacy_magnitude_gate(){let p=body(1,2,1_000_000_000_001,1);let f=Fields::parse(&p).unwrap();assert!(!f.legacy_supported());assert!(protocol::damage(&p).is_err());assert_eq!(f.hp_impact_candidate(),Some(1_000_000_000_000));}
#[test]fn legacy_amount_flags_and_high_prefix_behavior_are_preserved(){let mut p=body(0xffffffff00000065,999,957,915);p[32..39].copy_from_slice(&[1,6,0,8,16,0,0]);let d=protocol::damage(&p).unwrap();assert_eq!((d.actor,d.target,d.amount),(101,999,957));assert_eq!(d.flags,[true;5]);assert_eq!(d.raw_flags,[1,6,0,8,16,0,0]);}
#[test]fn opaque_short_and_parsed_partition_is_exhaustive_and_memory_stays_bounded(){let mut s=Survey::default();let bytes=s.owned_bytes();s.observe(at(0),0,&[0;53],false);s.observe(at(1),1,&[0;52],true);for n in 0..EVIDENCE_CAPACITY+17{s.observe(at(n as u64+2),3,&body(1,2,100,20),true);}assert_eq!(s.counts.seen,s.counts.opaque+s.counts.short+s.counts.parsed);assert_eq!(s.retained(),EVIDENCE_CAPACITY);assert_eq!(s.evicted,17);assert_eq!(s.owned_bytes(),bytes);assert!(bytes<=132*1024,"diagnostic field evidence owns {bytes} bytes");}
#[test]fn self_and_peer_fields_follow_same_path_and_meter_keeps_raw_amount(){let mut r=Replay::new(true);r.live_scope=true;let key=r.meter.registry.observe(0,r.meter.binding,101).unwrap();r.meter.registry.self_key=Some(key);let mut p=protocol::encode_frame(21196,&body(101,999,957,915));p.extend(protocol::encode_frame(21196,&body(202,999,957,915)));r.feed(segment(p)).unwrap();assert_eq!(r.meter.raw_hits.front().unwrap().source,key);assert_eq!(r.damage_wire.counts.parsed,2);assert!(r.damage_wire.observations().all(|o|o.fields.hp_impact_candidate()==Some(42)));assert_eq!(r.meter.session.total.hits,2);assert_eq!(r.meter.session.total.damage,1914);}
#[test]fn later_body_is_acknowledged_when_earlier_semantic_handler_fails(){let mut r=Replay::new(true);r.live_scope=true;let affected=r.meter.registry.observe(0,r.meter.binding,2).unwrap();for instance in 0..32768{r.combat.effects.insert((affected,instance),mabi_meter_core::combat::Effect{affected,instance,id:1,time_bits:0,stacks:0,source:None,first:at(0),last:at(0)});}let mut p=vec![0;36];p[..8].copy_from_slice(&2u64.to_le_bytes());p[8..16].copy_from_slice(&u64::MAX.to_le_bytes());p[16..20].copy_from_slice(&10u32.to_le_bytes());p[28..36].copy_from_slice(&1u64.to_le_bytes());let mut data=protocol::encode_frame(170069,&p);data.extend(protocol::encode_frame(21196,&body(1,2,957,915)));r.feed(segment(data)).unwrap();assert!(r.semantic_error.is_none());assert_eq!(r.meter.session.total.damage,957);assert_eq!(r.diagnostics.0["semantic_enrichment_degraded"],1);assert_eq!(r.damage_wire.counts.parsed,1);assert_eq!(r.damage_wire.observations().next().unwrap().at.frame,2);}
